  for (let ai = 0; ai < ranges.length; ai++) {
    for (let bi = 0; bi < ranges.length; bi++) {
      n++
      const a = ranges[ai], b = ranges[bi]
      let o, c, bf
      try { o = orig(a, b, opts) } catch (e) { o = 'ERR' }
      try { c = cur(a, b, opts) } catch (e) { c = 'ERR' }
      bf = brute(oi, ai, bi)
      if (o === 'empty' || c === 'empty' || bf === 'empty' || o === 'ERR' || c === 'ERR') continue
      if (o !== c) {
        changed++
        if (bf === o && bf !== c) { regress++; if (regress < 30) lines.push('REGRESS ' + JSON.stringify(a) + ' ⊆ ' + JSON.stringify(b) + ' ' + JSON.stringify(opts||null) + ' orig=' + o + ' new=' + c + ' brute=' + bf) }
