from pathlib import Path
p = Path('ranges/subset.js')
s = p.read_text()
old = """//   - If EQ satisfies every C, return true
//   - Else return false
// - If GT
//   - If GT.semver is lower than any > or >= comp in C, return false
//   - If GT is >=, and GT.semver does not satisfy every C, return false
//   - If GT.semver has a prerelease, and not in prerelease mode
//     - If no C has a prerelease and the GT.semver tuple, return false
// - If LT
//   - If LT.semver is greater than any < or <= comp in C, return false
//   - If LT is <=, and LT.semver does not satisfy every C, return false
//   - If LT.semver has a prerelease, and not in prerelease mode
//     - If no C has a prerelease and the LT.semver tuple, return false"""
new = """//   - If EQ satisfies the simple range C, return true
//   - Else return false
// - If GT
//   - If GT.semver is lower than any > or >= comp in C, return false
//   - If GT is >=, and GT.semver does not satisfy the simple range C, return
//     false
//   - If GT.semver has a prerelease, and not in prerelease mode
//     - If no C has a prerelease and the GT.semver tuple, return false
// - If LT
//   - If LT.semver is greater than any < or <= comp in C, return false
//   - If LT is <=, and LT.semver does not satisfy the simple range C, return
//     false
//   - If LT.semver has a prerelease, and not in prerelease mode
//     - If no C has a prerelease and the LT.semver tuple, return false
//
// "Satisfies the simple range C" means every comparator in C accepts the
// version, *plus* the prerelease rule, which C applies as a whole and not
// comparator by comparator: a prerelease version is only accepted when one of
// the comparators carries a prerelease of the same tuple.  Checking C one
// comparator at a time would reject, eg, `6.3.0-rc.5` for `<7.0.0-0`, even
// though `>=6.3.0-rc.4 <7.0.0-0` accepts it, which is what makes
// `^6.3.0-rc.5` a subset of `^6.3.0-rc.4`."""
assert s.count(old) == 1
s = s.replace(old, new)
p.write_text(s)
print('ok')
