function mk(n){const out=[];for(const o1 of ops)for(const v1 of vers){out.push([o1+v1]);if(n<2)continue;for(const o2 of ops)for(const v2 of vers)out.push([o1+v1,o2+v2])}return out}
let seed = 999
const rnd = () => (seed = (seed*1103515245+12345) % 2147483648) / 2147483648
