function comps(str, o) { try { return new Range(str, o||{}).set } catch(e){ return null } }
function hasPrereleaseEqWithGtLt(subSet) {
  // subSet: array of arrays (OR branches); check any branch with an EQ comp carrying prerelease + a gt/lt
  for (const branch of subSet) {
    const hasEqPre = branch.some(c => !c.operator && c.semver !== Comparator.ANY && c.semver.prerelease.length)
    const hasGt = branch.some(c => c.operator === '>' || c.operator === '>=')
    const hasLt = branch.some(c => c.operator === '<' || c.operator === '<=')
    if (hasEqPre && (hasGt || hasLt)) return true
  }
  return false
}
function unboundedSub(subSet, domSet) {
  // sub has gt but no lt while dom has lt, or sub has lt but no gt while dom has gt (in same branch)
  for (const b of subSet) {
    const hasGt = b.some(c => c.operator === '>' || c.operator === '>=')
    const hasLt = b.some(c => c.operator === '<' || c.operator === '<=')
    if (hasGt && !hasLt && domSet.some(d => d.some(c => c.operator === '<' || c.operator === '<='))) return true
    if (hasLt && !hasGt && domSet.some(d => d.some(c => c.operator === '>' || c.operator === '>='))) return true
  }
  return false
}

