    const famA = hasPrereleaseEqWithGtLt(subR)
    if (famA) stats.fp_A++
    else { stats.fp_OTHER++; if (other.length<15) other.push({kind:'FP-OTHER', sub:subS, dom:domS, o:o&&JSON.stringify(o), witness:Ustr[witness], old:ores}) }
    if (ores === false) { stats.regressFP++; if (other.length<15) other.push({kind:'FP-REGRESS', sub:subS, dom:domS, o:o&&JSON.stringify(o), witness:Ustr[witness]}) }
  } else if (nres === false && !witness && subAny) {
