    if (famB) stats.fn_B++
    else { stats.fn_OTHER++; if (other.length<15) other.push({kind:'FN-OTHER', sub:subS, dom:domS, o:o&&JSON.stringify(o), old:ores}) }
    if (ores === true) { stats.regressFN++; if (other.length<15) other.push({kind:'FN-REGRESS', sub:subS, dom:domS, o:o&&JSON.stringify(o)}) }
  } else if (nres === true && ores === false && witness === null) {
    stats.fixedOK++
  }
}
