def extractable(ver, build, inp):
    """new result must be derivable from input: components appear in order,
    zero-filled .0 parts may be absent from input."""
    base = inp[1:] if inp.startswith('v') else inp
    core, _, pre = ver.partition('-')
    toks = []
    parts = core.split('.')
    if parts[0] != '0' or True: toks.append(parts[0])
    for p in parts[1:]:
        if p != '0': toks.append(p)
    if pre:
        toks += pre.split('.')
    if build:
        toks += build.split('.')
    pos = 0
    for t in toks:
        i = base.find(t, pos)
        if i < 0: return False
        pos = i + len(t)
